namespace sv_a9820cc2194b441bb9460cc8aa7b8120.Services;

public record TaskItem(int Id, string Title, string Assignee, string Priority, DateTime DueDate, string Status);

public interface ITaskService
{
    Task<List<TaskItem>> GetAllTasksAsync();
    Task<TaskItem> CreateTaskAsync(string title, string assignee, string priority, DateTime dueDate);
    Task UpdateTaskStatusAsync(int taskId, string newStatus);
}

@page "/board"
@using sv_a9820cc2194b441bb9460cc8aa7b8120.Services
@rendermode InteractiveServer
@inject ITaskService TaskService

<PageTitle>Kanban Board</PageTitle>

<h1>Project Board</h1>

@if (isLoading)
{
    <p class="loading-message">Loading tasks...</p>
}
else if (errorMessage is not null)
{
    <p class="error-message">@errorMessage</p>
}
else
{
    <BoardStatsBar Tasks="allTasks" />
    <BoardSearchBar SearchTerm="@searchTerm" SearchTermChanged="OnSearchChanged" />

    <div class="kanban-board">
        <KanbanColumn Title="To Do"
                      Tasks="GetFilteredTasks("To Do")"
                      CanMoveLeft="false"
                      CanMoveRight="true"
                      OnMoveRight="MoveRight"
                      OnTaskCreated="data => CreateTask(data, "To Do")" />

        <KanbanColumn Title="In Progress"
                      Tasks="GetFilteredTasks("In Progress")"
                      CanMoveLeft="true"
                      CanMoveRight="true"
                      OnMoveLeft="MoveLeft"
                      OnMoveRight="MoveRight"
                      OnTaskCreated="data => CreateTask(data, "In Progress")" />

        <KanbanColumn Title="Done"
                      Tasks="GetFilteredTasks("Done")"
                      CanMoveLeft="true"
                      CanMoveRight="false"
                      OnMoveLeft="MoveLeft"
                      OnTaskCreated="data => CreateTask(data, "Done")" />
    </div>
}

@code {
    private List<TaskItem> allTasks = new();
    private string searchTerm = string.Empty;
    private bool isLoading = true;
    private string? errorMessage;

    private static readonly string[] Statuses = { "To Do", "In Progress", "Done" };

    protected override async Task OnInitializedAsync()
    {
        try
        {
            allTasks = await TaskService.GetAllTasksAsync();
        }
        catch (Exception ex)
        {
            errorMessage = $"Failed to load tasks: {ex.Message}";
        }
        finally
        {
            isLoading = false;
        }
    }

    private List<TaskItem> GetFilteredTasks(string status)
    {
        var tasks = allTasks.Where(t => t.Status == status);
        if (!string.IsNullOrWhiteSpace(searchTerm))
        {
            tasks = tasks.Where(t => t.Title.Contains(searchTerm, StringComparison.OrdinalIgnoreCase));
        }
        return tasks.ToList();
    }

    private void OnSearchChanged(string value)
    {
        searchTerm = value;
    }

    private async Task MoveLeft(TaskItem task)
    {
        var currentIndex = Array.IndexOf(Statuses, task.Status);
        if (currentIndex > 0)
        {
            var newStatus = Statuses[currentIndex - 1];
            await TaskService.UpdateTaskStatusAsync(task.Id, newStatus);
            allTasks = allTasks.Select(t => t.Id == task.Id ? t with { Status = newStatus } : t).ToList();
        }
    }

    private async Task MoveRight(TaskItem task)
    {
        var currentIndex = Array.IndexOf(Statuses, task.Status);
        if (currentIndex < Statuses.Length - 1)
        {
            var newStatus = Statuses[currentIndex + 1];
            await TaskService.UpdateTaskStatusAsync(task.Id, newStatus);
            allTasks = allTasks.Select(t => t.Id == task.Id ? t with { Status = newStatus } : t).ToList();
        }
    }

    private async Task CreateTask((string Title, string Assignee, string Priority, DateTime DueDate) data, string status)
    {
        var newTask = await TaskService.CreateTaskAsync(data.Title, data.Assignee, data.Priority, data.DueDate);
        allTasks.Add(newTask with { Status = status });
    }
}

